// 입력 검증 + OpenAI 요청 본문 구성
const MODEL = 'gpt-4.1-mini';
const MAX_CHARS = 4000;

const body = $input.first().json.body || {};
const transcript = String(body.transcript || '').trim();
const question = String(body.question || '').slice(0, 500);
const kind = String(body.kind || '');
const words = transcript ? transcript.split(/\s+/).filter(Boolean).length : 0;

if (!transcript) {
  return [{ json: { ok: false, error: '스크립트가 비어 있어요.' } }];
}
if (words < 8) {
  return [{ json: { ok: false, error: '문장이 너무 짧아 평가할 수 없어요. 8단어 이상 말해 보세요.' } }];
}
if (transcript.length > MAX_CHARS) {
  return [{ json: { ok: false, error: '스크립트가 너무 길어요(4000자 이하).' } }];
}

const system = [
  'You are an OPIc (ACTFL Oral Proficiency Interview) rater for a Korean learner.',
  'Evaluate ONLY the written transcript. You cannot judge pronunciation, intonation, or pauses.',
  'Judge: task completion, tense consistency, connectors and organization, vocabulary range, sentence length and fluency signals (written form), and fit to the question type (survey / surprise / roleplay).',
  'Write all feedback in Korean. Keep English examples inside quotes.',
  'Return ONLY a JSON object with this exact shape:',
  '{"grade": string (estimated OPIc grade, e.g. "IM1"), "summary": string, "good": string[], "problems": [{"issue": string, "fix": string}], "actions": string[]}',
  'good: 2-3 concrete strengths. problems: 2-5 concrete issues tied to the transcript. actions: 3 priorities for the next attempt, concrete and actionable.'
].join('\n');

const user = [
  'Question type: ' + kind,
  'Question (English): ' + question,
  'Transcript (' + words + ' words):',
  transcript
].join('\n');

const openaiBody = {
  model: MODEL,
  temperature: 0.3,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: user }
  ]
};

return [{ json: { ok: true, openaiBody } }];

// OpenAI 응답 해석 + 기록 형식 보정 (MOCK_REVIEWS와 같은 필드)
if ($json.error) {
  const msg = $json.error.message || 'OpenAI API 오류';
  return [{ json: { error: 'AI 평가 오류: ' + msg } }];
}
if (!$json.choices || !$json.choices[0]) {
  return [{ json: { error: 'AI 응답이 비어 있어요. 잠시 후 다시 시도해 주세요.' } }];
}
let r;
try {
  r = JSON.parse($json.choices[0].message.content || '{}');
} catch (e) {
  return [{ json: { error: 'AI 응답을 해석하지 못했어요. 다시 시도해 주세요.' } }];
}
const arr = (v) => (Array.isArray(v) ? v.map((x) => String(x)) : []);
const problems = Array.isArray(r.problems)
  ? r.problems.map((p) => ({ issue: String((p && p.issue) || ''), fix: String((p && p.fix) || '') }))
  : [];
return [{
  json: {
    result: {
      grade: String(r.grade || ''),
      summary: String(r.summary || ''),
      good: arr(r.good),
      problems,
      actions: arr(r.actions)
    }
  }
}];
